            <button onClick={() => setUsCfPeriodView('quarter')} style={{padding:'0.24rem 0.7rem', borderRadius:'6px', border:'none', cursor:'pointer', fontSize:'0.72rem', fontWeight:600, background: usCfPeriodView==='quarter' ? 'rgba(34,197,94,0.2)' : 'rgba(255,255,255,0.06)', color: usCfPeriodView==='quarter' ? '#22c55e' : 'var(--text-secondary)'}}>분기</button>
